; idioms.asm -- chapter 11: questions asked of A, each with its jump
; generated by gen11.py
        INCLUDE "msx.inc"
        OUTPUT "idioms.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
ANSWERS EQU $D000               ; a byte for each value of A
; Five ways to ask about A without CP, and one with it, each followed by its
; jump, for every value of A. The answers, one bit each, go into a byte for
; each A, the first test in bit 2 and the last in bit 7.
init:   di
        ld sp, SYS_AREA
        ld hl, ANSWERS
        ld d, 0                 ; D: every value of A
next:   ld c, 0
        ld a, d
        or a                    ; negative?
        jp m, y0
        or a                    ; no: the carry clear
        jr done0
y0:     scf                     ; yes: the carry set
done0:  rr c                    ; the answer into C, from the top
        ld a, d
        and %00001111           ; a multiple of 16?
        jr z, y1
        or a                    ; no: the carry clear
        jr done1
y1:     scf                     ; yes: the carry set
done1:  rr c                    ; the answer into C, from the top
        ld a, d
        bit 0, a                ; odd?
        jr nz, y2
        or a                    ; no: the carry clear
        jr done2
y2:     scf                     ; yes: the carry set
done2:  rr c                    ; the answer into C, from the top
        ld a, d
        dec a                   ; it was 1?
        jr z, y3
        or a                    ; no: the carry clear
        jr done3
y3:     scf                     ; yes: the carry set
done3:  rr c                    ; the answer into C, from the top
        ld a, d
        inc a                   ; it was 255?
        jr z, y4
        or a                    ; no: the carry clear
        jr done4
y4:     scf                     ; yes: the carry set
done4:  rr c                    ; the answer into C, from the top
        ld a, d
        cp 100                  ; 100 or more?
        jr nc, y5
        or a                    ; no: the carry clear
        jr done5
y5:     scf                     ; yes: the carry set
done5:  rr c                    ; the answer into C, from the top
        ld (hl), c
        inc hl
        inc d
        jr nz, next
stop:   jr stop
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
